    ["5"]="<HTML>$B <BODY>$B <H1 align=\"center\">İTTİFAKIN FİRMA RAKAMLARI</H1><BR/>$B <P align=\"center\">Part 1</P>$B <IMG src=\"Interface\\PvPRankBadges\\PvPRank14\" align=\"left\"/><BR/>$B <P align=\"right\">Grand Marshal</P><BR/><BR/>$B <IMG src=\"Interface\\PvPRankBadges\\PvPRank13\" align=\"left\"/><BR/>$B <P align=\"right\">Field Marshal</P><BR/><BR/>$B <IMG src=\"Interface\\PvPRankBadges\\PvPRank12\" align=\"left\"/><BR/>$B <P align=\"right\">Mareşal</P><BR/><BR/>$B <IMG src=\"Interface\\PvPRankBadges\\PvPRank11\" align=\"left\"/><BR/>$B <P align=\"right\">Komutan</P><BR/><BR/>$B <IMG src=\"Interface\\PvPRankBadges\\PvPRank10\" align=\"left\"/><BR/>$B <P align=\"right\">Teğmen Komutan</P><BR/><BR/>$B </BODY>$B </HTML>",
    ["6"]="<HTML>$B <BODY>$B <H1 align=\"center\">İTTİFAKIN RÜTBELERİ</H1><BR/>$B <P align=\"center\">Bölüm 2</P>$B <IMG src=\"Interface\\PvPRankBadges\\PvPRank09\" align=\"left\"/><BR/>$B <P align=\"right\">Knight- Şampiyon</P><BR/><BR/>$B <IMG src=\"Interface\\PvPRankBadges\\PvPRank08\" align=\"left\"/><BR/>$B <P align=\"right\">Şövalye- Kaptan</P><BR/><BR/>$B <IMG src=\"Interface\\PvPRankBadges\\PvPRank07\" align=\"left\"/><BR/>$B <P align=\"right\">Şövalye- Teğmen</P><BR/><BR/>$B <IMG src=\"Interface\\PvPRankBadges\\PvPRank06\" align=\"left\"/><BR/>$B <P align=\"right\">Şövalye</P><BR/><BR/>$B </BODY>$B </HTML>",
